-- =====================================================================
with owner as (
  select u.id::text as uid
    from auth.users u
    join public.app_owners a on lower(u.email) = lower(a.email)
   limit 1
)
insert into public.docs (collection, id, data)
select v.collection,
       replace(v.id, 'u_YuL8k7Mw0B4o9cu3U5BdmQ', owner.uid),
       replace(v.data, 'u_YuL8k7Mw0B4o9cu3U5BdmQ', owner.uid)::jsonb
  from (values
  ('events', '5ihc0ohd64mvfmunbdgq', $j${"aoName":"Andrea Pozzi","aoUid":"u_YuL8k7Mw0B4o9cu3U5BdmQ","createdAt":"2026-10-14T20:10:07.526Z","date":"2026-11-27","days":2,"deadline":"2026-10-15","deadlineCancel":"2026-10-15","desc":"Cari soci,\ndieci anni dopo il “National Winter Rally” che nel 2016 ha visto Genova protagonista del grande evento nazionale di fine stagione, il Genova Chapter ripropone ciò che dieci anni fa ha fatto incontrare 2.000 harleysti nella splendida location del Padiglione Blu della Fiera del Mare di Genova.\n\nQuest'anno ci aspettano due giorni con due feste pazzesche, sempre nella stessa location:\n\nVENERDI' 27 Novembre 2026 - Padiglione Blu della Fiera del Mare di Genova\nNotte prima di HOG INVERNO per celebrare i vent'anni di Assicuriamolatuapassione\n\nSABATO 28 Novembre 2026 - Padiglione Blu della Fiera del Mare di Genova\nHOG INVERNO - TEN YEARS AFTER, AGAIN!\n\nLa preparazione di queste due giornate è molto impegnativa ma il Genova Chapter e la Concessionaria HD di Genova possono contare su una grande squadra che cercherà di farci divertire e di accoglierci con la squisita e ormai famosa accoglienza genovese.\n\nLa nostra partecipazione avverrà con tre possibili scelte:\n• Pacchetto “FULL HOG INVERNO 2026”, sia venerdì che sabato con entrambe le feste e pernottamento secondo i seguenti costi:\n- € 300 in stanza singola\n- € 250 a persona in stanza doppia\n\n• Pacchetto “HOG INVERNO PARTY & NIGHT”, festa sabato e pernottamento secondo i seguenti costi:\n- € 170 in stanza singola\n- € 140 a persona in stanza doppia\n\nEntrambe le soluzioni in pernottamento comprensive di colazione a buffet, tassa di soggiorno, parcheggio all’aperto non custodito, wifi.\n\n• Pacchetto “HOG INVERNO PARTY ONLY”, solo festa del sabato con rientro in serata:\n- € 85 a persona\n\nNon ci hanno ancora dato informazioni per la maglietta evento, appena avremo notizie vi aggiorneremo.\n\nIl termine per l’iscrizione è stretto, quindi affrettatevi!\n\nRicordate di compilare il modulo di scarico responsabilità e che la Tessera HOG deve essere in corso di validità.\n\nPer info: cinzia.activities.officer@legnanochapter.it\nTel. 342 87 36 470","km":350,"mapUrl":"","maxSeats":30,"meetPlace":"Genova","meetTime":"07:00","onlyF":false,"onlyM":false,"packages":[{"alloggio":"Doppia","desc":"Venerdì e sabato Hog Inverno in stanza doppia","giorni":"2","id":"ai38ov1lr6sxp13nqkes","name":"FULL HOG INVERNO 2026 stanza doppia","price":250},{"alloggio":"Solo Run","desc":"Solo notte di Sabato","giorni":"1","id":"x7yuder9afk1acwgyxub","name":"FULL HOG INVERNO 2026 stanza singola","price":180}],"payInfo":"BONIFICO BANCARIO ASS.NE SPORTIVA DILETTANTISTICA LEGNANO CHAPTER ITALY IBAN IT 68 S 02008 20201 000100585568","price":0,"roomsDouble":22,"roomsNote":"","roomsQuad":0,"roomsSingle":8,"roomsTriple":0,"route":"","status":"open","tipologia":"premi","title":"HOG INVERNO 2026 - GENOVA - 27/28 novembre 2026"}$j$),
  ('events', '74zn5ztvcp1hxkbwfig2', $j${"aoName":"Andrea","aoUid":"u_YuL8k7Mw0B4o9cu3U5BdmQ","createdAt":"2026-10-14T19:37:56.956Z","date":"2026-10-28","days":1,"deadline":"","deadlineCancel":"","desc":"ratelli e sorelle di strada, preparatevi… la notte più mostruosa dell’anno sta arrivando! 🎃\n\nVi aspetta una CENA DA BRIVIDO all’Osteria del Sagrantino, tra streghe, zombie, bikers infernali e creature di ogni genere… rigorosamente TUTTI IN MASCHERA! Più sarete irriconoscibili, meglio sarà!🧛🧟🧙\n\nGran finale del TORNEO DI FLIP 7: sangue freddo, nervi saldi e un pizzico di fortuna… perché alla fine, uno solo salirà sul trono!\nE se non siete arrivati in finale, niente paura… ci saranno tanti altri giochi per divertirsi!\n\nUna cosa è certa: tra risate, brindisi e qualche brivido, sarà una serata da ricordare!\n\nCosto: 30 euro\n\nRitrovo Osteria del Sagrantino ore 19:30 – inizio cena ore 19:45\nvia San Genesio 1 Olgiate Olona\n\nOBBLIGATORIO: spirito biker e voglia di divertirsi! Le scuse non sono ammesse… nemmeno se avete paura dei fantasmi! 👻\nratelli e sorelle di strada, preparatevi… la notte più mostruosa dell’anno sta arrivando! 🎃\n\nVi aspetta una CENA DA BRIVIDO all’Osteria del Sagrantino, tra streghe, zombie, bikers infernali e creature di ogni genere… rigorosamente TUTTI IN MASCHERA! Più sarete irriconoscibili, meglio sarà!🧛🧟🧙\n\nGran finale del TORNEO DI FLIP 7: sangue freddo, nervi saldi e un pizzico di fortuna… perché alla fine, uno solo salirà sul trono!\nE se non siete arrivati in finale, niente paura… ci saranno tanti altri giochi per divertirsi!\n\nUna cosa è certa: tra risate, brindisi e qualche brivido, sarà una serata da ricordare!\n\nCosto: 30 euro\n\nRitrovo Osteria del Sagrantino ore 19:30 – inizio cena ore 19:45\nvia San Genesio 1 Olgiate Olona\n\nOBBLIGATORIO: spirito biker e voglia di divertirsi! Le scuse non sono ammesse… nemmeno se avete paura dei fantasmi! 👻","km":0,"mapUrl":"","maxSeats":0,"meetPlace":"Osteria Sagrantino","meetTime":"19: